#!/usr/bin/env python3
"""Create final N2-V2 I4 full-frame blinded review handoff from I3."""
from __future__ import annotations
import hashlib,json,shutil
from pathlib import Path
from PIL import Image
ROOT=Path(__file__).resolve().parent; I3=ROOT/'evidence/n2_v2_i3_20260922'; I4=ROOT/'evidence/n2_v2_i4_20260922'
def sha(path):
 h=hashlib.sha256()
 with path.open('rb') as s:
  for c in iter(lambda:s.read(1048576),b''):h.update(c)
 return h.hexdigest()
def write(path,value): path.parent.mkdir(parents=True,exist_ok=True); path.write_text(json.dumps(value,indent=2,sort_keys=True,ensure_ascii=False,allow_nan=False)+'\n')
def html(reviewer_id,card_ids,manifest_sha):
 cards=json.dumps(card_ids,separators=(',',':')); return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>N2-V2 {reviewer_id}</title><style>body{{font:16px sans-serif;max-width:1050px;margin:auto;background:#222;color:#eee}}img{{width:960px;height:960px;object-fit:contain;background:#777}}button,select,input{{font-size:16px;margin:8px}}fieldset{{border:1px solid #888}}#progress{{float:right}}</style></head><body><h1>N2-V2 独立盲审 <span id="progress"></span></h1><p>不要查看 private、来源信息或另一位审查者结果；不要讨论。语义与四项 artifact 均须填写。</p><img id="card"><h2 id="cardid"></h2><fieldset><legend>背景语义</legend><select id="label"><option value="">请选择</option><option>AQUATIC_CONTEXT</option><option>NON_AQUATIC_CONTEXT</option><option>AMBIGUOUS</option></select></fieldset><fieldset><legend>artifact（任一 true 即拒绝）</legend><label><input type=checkbox id="visible_non_background_object">显著非背景物体</label><br><label><input type=checkbox id="donor_removal_or_fill_trace">移除/填充痕迹</label><br><label><input type=checkbox id="abnormal_compositing_boundary">异常合成边界</label><br><label><input type=checkbox id="other_arm_identity_cue">其他 arm identity 线索</label></fieldset><button id="prev">上一张</button><button id="save">保存并下一张</button><button id="export">全部完成后导出 JSON</button><script>const reviewer={json.dumps(reviewer_id)},manifest={json.dumps(manifest_sha)},cards={cards},fields=['visible_non_background_object','donor_removal_or_fill_trace','abnormal_compositing_boundary','other_arm_identity_cue'];let i=0,started=new Date().toISOString(),answers={{}};function show(){{let c=cards[i],a=answers[c]||{{}};document.getElementById('card').src='cards/'+c+'.png';document.getElementById('cardid').textContent=c;document.getElementById('label').value=a.semantic_label||'';for(let f of fields)document.getElementById(f).checked=!!a[f];document.getElementById('progress').textContent=(i+1)+' / '+cards.length}}function save(){{let c=cards[i],label=document.getElementById('label').value;if(!label){{alert('请选择语义标签');return false}}let a={{card_id:c,semantic_label:label}};for(let f of fields)a[f]=document.getElementById(f).checked;answers[c]=a;localStorage.setItem(reviewer,JSON.stringify({{i,started,answers}}));return true}}document.getElementById('save').onclick=()=>{{if(save()&&i<cards.length-1){{i++;show()}}}};document.getElementById('prev').onclick=()=>{{save();if(i>0){{i--;show()}}}};document.getElementById('export').onclick=()=>{{if(!save())return;let missing=cards.filter(c=>!answers[c]);if(missing.length){{alert('仍有 '+missing.length+' 张未完成');return}}let bundle={{schema_version:1,study_version:'N2_V2',review_bundle_id:'N2_V2_I4_'+reviewer+'_'+Date.now(),reviewer_id:reviewer,review_card_manifest_sha256:manifest,review_started_utc:started,review_completed_utc:new Date().toISOString(),independence_declaration:{{worked_independently:true,discussed_before_seal:false,model_outcomes_visible:false,source_or_arm_identity_visible:false}},reviews:cards.map(c=>answers[c])}};let blob=new Blob([JSON.stringify(bundle,null,2)+'\n'],{{type:'application/json'}}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=reviewer+'.json';a.click()}};let old=JSON.parse(localStorage.getItem(reviewer)||'null');if(old){{i=old.i||0;started=old.started||started;answers=old.answers||{{}}}}show();</script></body></html>'''
def main():
 if I4.exists():raise RuntimeError('I4_EXISTS')
 I4.mkdir(parents=True)
 for rel in ['private/scene_originals','private/recipient_images','private/recipient_masks']:
  shutil.copytree(I3/rel,I4/rel)
 shutil.copy2(I3/'private/openimages_mask_archive_bindings.json',I4/'private/openimages_mask_archive_bindings.json')
 scenes=json.loads((I3/'private/scene_candidate_registry.json').read_text()); scenes['attempt_id']='N2_V2_I4_20260922'
 card_records=[]
 for row in scenes['records']:
  source=I4/row['image_path']; target=I4/'review/cards'/(row['card_id']+'.png'); target.parent.mkdir(parents=True,exist_ok=True)
  with Image.open(source) as image:
   rgb=image.convert('RGB'); rgb.thumbnail((960,960),Image.Resampling.LANCZOS); canvas=Image.new('RGB',(960,960),(127,127,127)); canvas.paste(rgb,((960-rgb.width)//2,(960-rgb.height)//2)); canvas.save(target,format='PNG',compress_level=9)
  row['review_image_path']=str(target.relative_to(I4)); row['review_image_sha256']=sha(target)
  card_records.append({'card_id':row['card_id'],'image_path':str(target.relative_to(I4)),'image_sha256':sha(target)})
 write(I4/'private/scene_candidate_registry.json',scenes)
 recipients=json.loads((I3/'private/recipient_candidate_registry.json').read_text()); recipients['attempt_id']='N2_V2_I4_20260922'; write(I4/'private/recipient_candidate_registry.json',recipients)
 cards={'schema_version':1,'study_version':'N2_V2','attempt_id':'N2_V2_I4_20260922','blinding':{'source_id_hidden':True,'dataset_class_hidden':True,'candidate_stratum_hidden':True,'model_information_hidden':True,'randomization_key':'INHERITED_FROM_I3_SHA256_ATTEMPT_ID_COLON_ASSET_ID_ASCENDING','display_transform':'FULL_FRAME_ASPECT_PRESERVING_MAX_960_GREY_PAD_NO_CROP'},'records':card_records}; write(I4/'review/review_card_manifest.json',cards); card_sha=sha(I4/'review/review_card_manifest.json')
 template_reviews=[{'card_id':r['card_id'],'semantic_label':'REPLACE_WITH_AQUATIC_CONTEXT_NON_AQUATIC_CONTEXT_OR_AMBIGUOUS','visible_non_background_object':None,'donor_removal_or_fill_trace':None,'abnormal_compositing_boundary':None,'other_arm_identity_cue':None} for r in card_records]
 for reviewer in ('reviewer_A','reviewer_B'):
  write(I4/'review/templates'/(reviewer+'.json'),{'schema_version':1,'study_version':'N2_V2','review_bundle_id':'REPLACE_AFTER_COMPLETION','reviewer_id':reviewer,'review_card_manifest_sha256':card_sha,'review_started_utc':'REPLACE_RFC3339','review_completed_utc':'REPLACE_RFC3339','independence_declaration':{'worked_independently':True,'discussed_before_seal':False,'model_outcomes_visible':False,'source_or_arm_identity_visible':False},'reviews':template_reviews})
  (I4/'review'/(reviewer+'.html')).write_text(html(reviewer,[r['card_id'] for r in card_records],card_sha))
 (I4/'review/README.md').write_text('# N2-V2 双人独立盲审交接\n\n审查者 A 只打开 `reviewer_A.html`，审查者 B 只打开 `reviewer_B.html`。不要查看 `private/`、来源信息、另一位审查者的文件或模型信息；完成前不要讨论。浏览器会本地保存进度，102 张全部填写后点击导出 JSON。将两个导出的 JSON 分别交回，不要互看。\n\n语义标签只能是 `AQUATIC_CONTEXT`、`NON_AQUATIC_CONTEXT`、`AMBIGUOUS`。四个 artifact 字段逐项判断。任一审查者任一 artifact=true 将 union-reject。卡片为完整画面等比缩放并以灰色留边，没有裁切、内容填充或局部编辑。\n')
 prep={'schema_version':1,'study_version':'N2_V2','stage_id':'N2_V2_INPUT_IDENTIFIABILITY','attempt_id':'N2_V2_I4_20260922','status':'BLOCKED_INDEPENDENT_REVIEWERS','reason':'Full-frame blinded cards, licensed candidates, and two offline review forms are ready; two independent human bundles remain required.','predecessor_attempt_id':'N2_V2_I3_20260922','predecessor_status':'BLOCKED_INDEPENDENT_REVIEWERS','fresh_root_reason':'Replace center-cropped review displays with full-frame aspect-preserving cards and add sealed offline forms.','scene_candidate_count':102,'candidate_stratum_counts':{'AQUATIC_CANDIDATE_STRATUM':54,'NON_AQUATIC_CANDIDATE_STRATUM':48},'recipient_candidate_count':12,'review_card_count':102,'accepted_scene_asset_count':0,'sealed_review_bundle_count':0,'blind_review_status':'NOT_RUN_AWAITING_HUMANS','matching_status':'NOT_RUN_PRECEDING_GATE','identifiability_freeze':'NOT_ISSUED','behavior_gate':'NOT_AUTHORIZED','model_access_count':0,'checkpoint_access_count':0,'gpu_use_count':0};write(I4/'preparation_receipt.json',prep);print(json.dumps(prep,sort_keys=True))
if __name__=='__main__':main()
